 ]},
 {"clause_id": "c022", "issues": [
   {"issue": "\"[A]ll amounts required to be paid by Tenant under the terms of this Lease, including Section 6\" is a catch-all whose single enumerated example invites an expressio unius argument that only tax-type items are Additional Rent. Whether items such as the Section 4.4 service charge or Section 17.5 reimbursements are recoverable as Rent turns on this.", "type": 1, "prob": 0.12}
 ]},
 {"clause_id": "c023", "issues": [
